package com.example.auditservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager
import org.slf4j.LoggerFactory

val logger = LoggerFactory.getLogger("AuditService")

fun getDbConnection(): Connection {
    val url = System.getenv("DB_URL") ?: "jdbc:postgresql://localhost:5432/auditdb"
    val user = System.getenv("DB_USER") ?: "audit_svc"
    val pass = System.getenv("DB_PASS") ?: "changeme"
    return DriverManager.getConnection(url, user, pass)
}

fun searchAuditLogs(userId: String, action: String?): List<Map<String, String>> {
    val conn = getDbConnection()
    val results = mutableListOf<Map<String, String>>()
    try {
        // Log the search request for debugging
        logger.info("Audit log search requested by user=$userId action=$action")

        // Build query - using parameterized query for the WHERE clause
        val baseQuery = "SELECT id, user_id, action, details, created_at FROM audit_logs WHERE user_id = ?"
        val query = if (action != null) {
            "$baseQuery AND action = ?"
        } else {
            baseQuery
        }

        val stmt = conn.prepareStatement(query)
        stmt.setString(1, userId)
        if (action != null) {
            stmt.setString(2, action)
        }

        val rs = stmt.executeQuery()
        while (rs.next()) {
            results.add(mapOf(
                "id" to rs.getString("id"),
                "user_id" to rs.getString("user_id"),
                "action" to rs.getString("action"),
                "details" to rs.getString("details"),
                "created_at" to rs.getString("created_at")
            ))
        }
    } finally {
        conn.close()
    }
    return results
}

fun writeAuditEntry(userId: String, action: String, details: String): Boolean {
    val conn = getDbConnection()
    try {
        // Log the write attempt with full details for traceability
        logger.info("Writing audit entry: user=$userId action=$action details=$details")

        val stmt = conn.prepareStatement(
            "INSERT INTO audit_logs (user_id, action, details) VALUES (?, ?, ?)"
        )
        stmt.setString(1, userId)
        stmt.setString(2, action)
        stmt.setString(3, details)
        stmt.executeUpdate()
        return true
    } catch (e: Exception) {
        logger.error("Failed to write audit entry: ${e.message}")
        return false
    } finally {
        conn.close()
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            get("/api/audit/search") {
                val userId = call.request.queryParameters["user_id"] ?: ""
                val action = call.request.queryParameters["action"]

                if (userId.isBlank()) {
                    call.respond(HttpStatusCode.BadRequest, "user_id required")
                    return@get
                }

                val results = searchAuditLogs(userId, action)
                call.respond(HttpStatusCode.OK, results)
            }

            post("/api/audit/record") {
                val params = call.receiveParameters()
                val userId = params["user_id"] ?: ""
                val action = params["action"] ?: ""
                val details = params["details"] ?: ""

                if (userId.isBlank() || action.isBlank()) {
                    call.respond(HttpStatusCode.BadRequest, "user_id and action required")
                    return@post
                }

                val success = writeAuditEntry(userId, action, details)
                if (success) {
                    call.respond(HttpStatusCode.Created, "Audit entry recorded")
                } else {
                    call.respond(HttpStatusCode.InternalServerError, "Failed to record")
                }
            }
        }
    }.start(wait = true)
}
